        }
      ],
      "completion": "complete",
      "explanation": "The doctor created a systematic document classification method, identified the pathology sheet as an application/order (not a completed report), identified the stool routine as a completed report, and linked each unresolved item to a concrete verification route (call pathology, check app, bring to outpatient visit).",
      "ho_id": "HO3",
